# x0xd supervision wrapper. Generated by `x0x autostart` -- do not edit.
# Upgrade contract (ADR-0061 clause 3): x0xd exits with status 100 to ask
# for a restart on new bytes, and this script restarts it. Every other exit
# status is a real termination and is propagated. x0xd verifies this script
# (version, restart policy, executable and arguments) before it accepts a
# supervised upgrade; an edited script makes the daemon refuse self-update
# instead of exiting into an unknown policy.
$x0xWrapperVersion = __X0X_WRAPPER_VERSION__
$x0xExecutable = '__X0X_EXECUTABLE__'
$x0xArguments = @(__X0X_ARGUMENTS__)
$x0xRestartOnExit100 = $true
$env:X0X_SUPERVISED = '1'
$env:X0X_WRAPPER = $PSCommandPath
while ($true) {
    & $x0xExecutable @x0xArguments
    $x0xExit = $LASTEXITCODE
    if ($x0xExit -ne 100) { exit $x0xExit }
    Start-Sleep -Seconds 5
}
